compliant:
import { Effect } from "effect"

export interface OperationMetadata {
  readonly name: string
  readonly component: string
  readonly requestId: string
}

export const withOperationTelemetry = <A, E, R>(
  operation: Effect.Effect<A, E, R>,
  metadata: OperationMetadata
): Effect.Effect<A, E, R> =>
  operation.pipe(
    Effect.tap(() =>
      Effect.logDebug("Operation completed", {
        operation: metadata.name,
        requestId: metadata.requestId
      })
    ),
    Effect.tapError((error) =>
      Effect.logWarning("Operation failed", {
        operation: metadata.name,
        requestId: metadata.requestId,
        error
      })
    ),
    Effect.withSpan(metadata.name, {
      attributes: {
        "app.component": metadata.component,
        "app.request_id": metadata.requestId
      }
    })
  )
